import { JSDOM } from 'jsdom'
const dom = new JSDOM(`<style>
.a { color: green; }
#x { color: blue; }
</style>
<p id="x" class="a">hi</p>`)
const { document } = dom.window
const NAMES = {
  'rgb(255, 0, 0)': 'red',
  'rgb(0, 128, 0)': 'green',
  'rgb(0, 0, 255)': 'blue',
  'rgb(255, 165, 0)': 'orange',
}
const colourOf = (sel) => {
  const c = dom.window.getComputedStyle(
    document.querySelector(sel)).color
  return NAMES[c] ?? c
}
console.log(colourOf('p'))

